// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint[] calldata v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // The fuzzed caddress is an EOA with no code, so low-level call always succeeds.
        // According to ADVERSARIAL COUNTERPARTY rule, we need a helper that makes the call succeed.
        // Deploy a minimal helper that always returns true on transferFrom selector.
        TransferFromHelper helper = new TransferFromHelper();
        // Build call with the helper address instead of the fuzzed caddress
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, address(helper), _tos, v));
        assertTrue(ok && true); // this always passes; we need to observe c's return value.
        // Actually, we must observe c's return through a low-level call result.
    }
    function testFuzz_property2(address from, address[] calldata _tos, uint[] calldata v) public {
        // The bug is about return value difference. The adversarial counterparty is a callee that succeeds.
        // Even though an EOA call succeeds, we need code that doesn't revert to expose the difference.
        // Deploy helper that implements the transferFrom interface returning true.
        TransferFromHelper helper = new TransferFromHelper();
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // Call transfer and capture the return value
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, address(helper), _tos, v));
        require(success, "call failed");
        bool returned = abi.decode(ret, (bool));
        assertTrue(returned);
    }
}

contract TransferFromHelper {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 len, address from, address caddress, uint256 val) public {
        vm.assume(len > 0);
        address[] memory tos = new address[](len);
        uint[] memory vs = new uint[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(i, len)))));
            vs[i] = val;
        }
        bool ok;
        try c.transfer(from, caddress, tos, vs) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
